const form=document.querySelector('#form'),meta=document.querySelector('#meta');
let catalogCases=[];
function data(){const o={};new FormData(form).forEach((v,k)=>o[k]=v);['utc_offset_hours','clock_offset_seconds','takeoff_height_m','start_seconds','end_seconds','horizontal_fov_deg','yaw_offset_deg','resolution_m_per_px','horizon_margin','bottom_crop_percent','frame_interval'].forEach(k=>o[k]=Number(o[k]));['run_masking','run_tracking','run_velocities'].forEach(k=>o[k]=form.elements[k].checked);return o}
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const j=await r.json();if(r.status===404&&j.error==='Неизвестный запрос')throw Error('Сервер DroneVision запущен из старой версии программы: закройте его окно и запустите программу заново.');if(!r.ok)throw Error(j.error||'Ошибка запроса');return j}
function activity(node,text,state='idle'){if(!node)return;node.textContent=text;node.classList.toggle('status-working',state==='working');node.classList.toggle('status-done',state==='done');node.classList.toggle('status-error',state==='error')}
function note(text,bad=false){activity(meta,text,bad?'error':text.trim().endsWith('…')?'working':'done')}
function folderOf(path){return path?path.replace(/[/\\][^/\\]+$/,''):''}
// Paths come from the server in the form of its system: C:\\data\\x.MP4 on Windows, /data/x.MP4 elsewhere.
function baseName(path){return path?String(path).split(/[/\\]/).pop():''}
function joinPath(folder,name){return folder+(folder.includes('\\')&&!folder.includes('/')?'\\':'/')+name}
async function choose(button){const target=button.dataset.dialog,videoPath=form.elements.video_path.value;let start=target==='log_path'||target==='project_dir'?folderOf(videoPath):folderOf(form.elements[target].value);const j=await api('/api/dialog',{method:'POST',body:JSON.stringify({kind:button.dataset.kind||'file',filter:button.dataset.filter,start})});if(!j.path)return;form.elements[target].value=j.path;if(target==='video_path'){form.elements.log_path.value='';note('Видео выбрано — ищу подходящий лог…');await match();await inspectVideo();await openViewer(j.path)}}
document.querySelectorAll('[data-dialog]').forEach(b=>b.onclick=()=>choose(b).catch(e=>note(e.message,true)));
async function match(){const video_path=form.elements.video_path.value;if(!video_path)throw Error('Сначала выберите видео');const j=await api('/api/match',{method:'POST',body:JSON.stringify({video_path})});form.elements.log_path.value=j.log_path;form.elements.utc_offset_hours.value=j.utc_offset_hours;form.elements.clock_offset_seconds.value=j.clock_offset_seconds;note(`Найден ${baseName(j.log_path)} · SRT · расхождение GPS ${j.spatial_error_m} м`)}
document.querySelector('#match').onclick=()=>match().catch(e=>note(e.message,true));
async function inspectVideo(){note('Читаю метаданные…');const j=await api('/api/inspect',{method:'POST',body:JSON.stringify(data())}),v=j.video;document.querySelector('#duration').textContent=`— ${v.duration.toFixed(1)} с (${Math.floor(v.duration/60)}:${String(Math.round(v.duration%60)).padStart(2,'0')})`;note(`${v.width}×${v.height} · ${v.fps.toFixed(2)} fps · ${v.duration.toFixed(1)} с`);return v}
document.querySelector('#inspect').onclick=()=>inspectVideo().catch(e=>note(e.message,true));
form.onsubmit=e=>e.preventDefault();
function setStatus(title,detail,p,state='idle'){activity(document.querySelector('#statusText'),title,state);activity(document.querySelector('#detail'),detail,state);document.querySelector('#bar').style.width=`${p*100}%`}
async function poll(){try{const s=await api('/api/status'),state=s.status==='running'?'working':s.status==='done'?'done':s.status==='error'?'error':'idle';setStatus(s.status==='running'?'Идёт обработка…':s.status==='done'?'Обработка готова':s.status==='error'?'Ошибка':'Готов к работе',s.error||s.message,s.progress,state);document.querySelector('#outputPath').textContent=s.output?`Сохранено: ${s.output}`:'';if(s.status==='done'){const img=document.querySelector('#preview');img.src='/api/result?'+Date.now();img.style.display='block'}if(s.status==='running')setTimeout(poll,700)}catch(e){setStatus('Ошибка',e.message,0,'error')}}
// --- Cases: videos with telemetry found in the data folder (dronevision/catalog.py) ---
// The folder is asked for once and remembered on the server; when it is not available, it is asked for again.
function caseButton(c,i){const b=document.createElement('button'),date=document.createElement('span'),name=document.createElement('b'),text=document.createElement('small');b.type='button';b.className='case';b.disabled=!c.available;b.title=c.video_path;date.textContent=c.date;name.textContent=c.title?`${c.id} · ${c.title}`:c.id;text.textContent=c.description;b.append(date,name,text);b.onclick=()=>selectCase(i,b);return b}
function catalogAction(text,handler){const b=document.createElement('button');b.type='button';b.className='catalog-action';b.textContent=text;b.onclick=handler;return b}
async function chooseDataRoot(start){const j=await api('/api/dialog',{method:'POST',body:JSON.stringify({kind:'directory',start})});if(j.path)await setDataRoot(j.path)}
async function setDataRoot(path){activity(document.querySelector('#datasetRoot'),'Просматриваю папку…','working');renderCatalog(await api('/api/data-root',{method:'POST',body:JSON.stringify({path})}))}
async function refreshCatalog(){renderCatalog(await api('/api/catalog?refresh=1'))}
function renderCatalog(j){
  catalogCases=j.cases||[];
  const box=document.querySelector('#cases'),rootNode=document.querySelector('#datasetRoot'),actions=document.querySelector('#datasetActions');
  const guard=handler=>()=>handler().catch(e=>{activity(rootNode,e.message,'error');rootNode.classList.add('bad')});
  box.innerHTML='';actions.innerHTML='';rootNode.classList.remove('bad');box.classList.toggle('empty',!j.connected||!catalogCases.length);
  if(j.connected){
    activity(rootNode,`${j.root} · видео: ${j.total}, с телеметрией: ${j.usable}${j.total>catalogCases.length?` · показаны первые ${catalogCases.length}`:''}`,'done');
    catalogCases.forEach((c,i)=>box.append(caseButton(c,i)));
    if(!catalogCases.length){const empty=document.createElement('p');empty.className='data-prompt';empty.textContent='В этой папке нет видео. Выберите другую папку или своё видео ниже.';box.append(empty)}
    actions.append(catalogAction('Обновить',guard(refreshCatalog)),catalogAction('Сменить папку…',guard(()=>chooseDataRoot(j.root))));
  }else{
    const prompt=document.createElement('div'),text=document.createElement('p'),hint=document.createElement('small'),buttons=document.createElement('div');
    prompt.className='data-prompt';
    text.textContent=j.root?`Папка с данными недоступна: ${j.root}. Подключите диск и нажмите «Проверить снова» или укажите папку заново.`:'Укажите папку с данными — программа найдёт в ней все видео с телеметрией и покажет их здесь. Папка запоминается, в следующий раз спрашивать не будет.';
    hint.textContent='В папке — в любых подпапках — должны лежать видео (MP4/MOV), их SRT с тем же именем или номером DJI_XXXX и полётные логи DJIFlightRecord_*.txt. Пары подбираются автоматически.';
    buttons.append(catalogAction('Указать папку с данными…',guard(()=>chooseDataRoot(j.root||''))));
    if(j.root)buttons.append(catalogAction('Проверить снова',guard(refreshCatalog)));
    if(j.suggestion)buttons.append(catalogAction(`Использовать ${j.suggestion}`,guard(()=>setDataRoot(j.suggestion))));
    prompt.append(text,buttons,hint);box.append(prompt);
    activity(rootNode,j.root?'папка недоступна':'папка не указана',j.root?'error':'idle');
  }
  WHITE_SEA_0371=(catalogCases.find(c=>c.id==='DJI_0371'&&c.known&&c.available)||{}).video_path||'';
}
async function loadCatalog(){const node=document.querySelector('#datasetRoot');activity(node,'Проверяю папку данных…','working');try{renderCatalog(await api('/api/catalog'))}catch(e){activity(node,e.message,'error');node.classList.add('bad')}}
async function selectCase(index,button){document.querySelectorAll('.case').forEach(x=>x.classList.remove('selected'));button.classList.add('selected');const c=catalogCases[index];['video_path','project_dir','start_seconds','end_seconds','segments','resolution_m_per_px','frame_interval','yaw_offset_deg'].forEach(k=>form.elements[k].value=c[k]??0);document.querySelector('#duration').textContent=`— ${c.duration.toFixed(1)} с`;form.elements.log_path.value='';note('Подбираю FlightRecord по SRT и GPS…');try{await match();await inspectVideo();await openViewer(c.video_path)}catch(e){note(e.message,true)}}
const catalogReady=loadCatalog();

// --- Synchronized video and telemetry viewer ---
