function mediaUrl(path,quality){return `/api/video?path=${encodeURIComponent(path)}&quality=${encodeURIComponent(quality)}`}
function clock(value){const m=Math.floor(value/60),s=value-m*60;return `${String(m).padStart(2,'0')}:${s.toFixed(3).padStart(6,'0')}`}
async function openViewer(path=WHITE_SEA_0371){if(!path)throw Error('Сначала выберите видео: «Выбрать…» в разделе «Файлы»');const loading=document.querySelector('#videoLoading');activity(loading,'Сопоставляю SRT и FlightRecord…','working');loading.style.display='grid';try{viewer=await api('/api/viewer',{method:'POST',body:JSON.stringify({video_path:path})});form.elements.video_path.value=path;form.elements.log_path.value=viewer.log_path;form.elements.utc_offset_hours.value=viewer.sync.hours;form.elements.clock_offset_seconds.value=viewer.sync.seconds;selectedFrames=[];selectedIntervals=[];intervalStart=null;if(!form.elements.project_dir.value)form.elements.project_dir.value=joinPath(folderOf(path),'DroneVision-project');document.querySelector('#duration').textContent=`— ${viewer.video.duration.toFixed(1)} с`;document.querySelector('#viewerTitle').textContent=baseName(path);document.querySelector('#quality').value='original';video.src=mediaUrl(path,'original');video.load();const x=viewer.sync;document.querySelector('#viewerMeta').textContent=`${viewer.video.width}×${viewer.video.height} · ${viewer.video.fps.toFixed(2)} fps · ${viewer.video.duration.toFixed(1)} с · ${baseName(viewer.log_path)} · FlightRecord ${x.hours}ч ${x.seconds}с · начало SRT ${x.srt_start_correction_seconds>=0?'+':''}${x.srt_start_correction_seconds}с · GPS ±${x.gps_error_m}м${x.image_extra_seconds!=null?` · сдвиг уточнён по изображению (${x.image_extra_seconds>0?'+':''}${x.image_extra_seconds}с)`:x.ambiguous?` · ${x.note||'сдвиг лога по GPS не определён, принят 0'}`:''}`;renderSelections();updateTransport();drawAll()}finally{loading.style.display='none'}}
