function afterMetadata(fn){if(video.readyState>=1)fn();else video.addEventListener('loadedmetadata',fn,{once:true})}
document.querySelector('#quality').onchange=async e=>{if(!viewer)return;const at=video.currentTime,playing=!video.paused,q=e.target.value,loading=document.querySelector('#videoLoading');loading.style.display='grid';try{if(q!=='original'){activity(loading,`Готовлю ${q} proxy при первом запуске…`,'working');await api('/api/proxy',{method:'POST',body:JSON.stringify({video_path:viewer.video_path,height:Number(q.replace('p',''))})})}video.src=mediaUrl(viewer.video_path,q);video.load();afterMetadata(()=>{video.currentTime=Math.min(at,video.duration||at);if(playing)video.play().catch(()=>{});loading.style.display='none'})}catch(error){activity(loading,error.message,'error')}};
playButton.onclick=()=>{if(!viewer)return;video.paused?video.play():video.pause()};
function stepFrame(direction){if(!viewer)return;video.pause();const fps=viewer.video.fps;video.currentTime=Math.max(0,Math.min(viewer.video.duration,Math.round(video.currentTime*fps+direction)/fps));updateTransport();drawAll()}
document.querySelector('#prevFrame').onclick=()=>stepFrame(-1);
document.querySelector('#nextFrame').onclick=()=>stepFrame(1);
rateButton.onclick=()=>{rateIndex=(rateIndex+1)%rates.length;video.playbackRate=rates[rateIndex];rateButton.textContent=`${rates[rateIndex]}×`};
function updateTransport(){document.querySelector('#timecode').textContent=`${clock(video.currentTime)} / ${clock((viewer&&viewer.video.duration)||video.duration||0)}`;playButton.textContent=video.paused?'▶':'❚❚'}
['timeupdate','seeked','loadedmetadata','play','pause'].forEach(event=>video.addEventListener(event,()=>{updateTransport();drawAll()}));
function animatePlayback(){if(video.paused)return;updateTransport();drawAll();animationFrame=requestAnimationFrame(animatePlayback)}
video.addEventListener('play',()=>{cancelAnimationFrame(animationFrame);animationFrame=requestAnimationFrame(animatePlayback)});
video.addEventListener('pause',()=>cancelAnimationFrame(animationFrame));
function snapTime(value){return viewer?Math.round(value*viewer.video.fps)/viewer.video.fps:value}
function frameSelection(time=video.currentTime){const time_s=snapTime(time);return {time_s,frame_index:Math.round(time_s*viewer.video.fps),horizon_offset_percent:Number(horizonOffset.value)||0,bottom_crop_percent:Number(bottomCropPercent.value)||0,adjustments:{...DV.adjust.params()}}}
function nearestSelectedFrame(){return selectedFrames.length?selectedFrames.reduce((best,item)=>Math.abs(item.time_s-video.currentTime)<Math.abs(best.time_s-video.currentTime)?item:best,selectedFrames[0]):null}
document.querySelector('#markFrame').onclick=()=>{if(!viewer)return;const item=frameSelection(),index=selectedFrames.findIndex(selected=>selected.frame_index===item.frame_index),updated=index>=0;if(updated)selectedFrames[index]=item;else selectedFrames.push(item);selectedFrames.sort((a,b)=>a.frame_index-b.frame_index);renderSelections();document.querySelector('#projectionStatus').textContent=updated?`Кадр ${clock(item.time_s)} обновлён с текущими настройками.`:`Кадр ${clock(item.time_s)} добавлен.`};
document.querySelector('#markIn').onclick=()=>{if(viewer){intervalStart=snapTime(video.currentTime);renderSelections()}};
document.querySelector('#markOut').onclick=()=>{if(viewer&&intervalStart!==null){const end=snapTime(video.currentTime);if(end>intervalStart){selectedIntervals.push([intervalStart,end]);selectedIntervals.sort((a,b)=>a[0]-b[0]);intervalStart=null;renderSelections()}}};
function removeButton(title,handler){const b=document.createElement('button');b.type='button';b.title=title;b.setAttribute('aria-label',title);b.textContent='×';b.onclick=handler;return b}
function renderSelections(){const box=document.querySelector('#selections');box.innerHTML='';selectedFrames.forEach((item,i)=>{const x=document.createElement('span');x.title=`Кадр ${item.frame_index} · горизонт ${item.horizon_offset_percent>0?'+':''}${item.horizon_offset_percent.toFixed(1)}% · обрезка ${item.bottom_crop_percent.toFixed(1)}%`;x.append(document.createTextNode(`Кадр ${clock(item.time_s)}`),removeButton('Удалить метку',()=>{selectedFrames.splice(i,1);renderSelections()}));box.append(x)});selectedIntervals.forEach((r,i)=>{const x=document.createElement('span');x.append(document.createTextNode(`Интервал ${clock(r[0])}–${clock(r[1])}`),removeButton('Удалить интервал',()=>{selectedIntervals.splice(i,1);renderSelections()}));box.append(x)});if(intervalStart!==null){const x=document.createElement('span');x.append(document.createTextNode(`Начало ${clock(intervalStart)} · выберите конец`),removeButton('Отменить начало интервала',()=>{intervalStart=null;renderSelections()}));box.append(x)}form.elements.segments.value=selectedIntervals.map(r=>`${r[0].toFixed(3)}-${r[1].toFixed(3)}`).join(', ');if(selectedIntervals.length){form.elements.start_seconds.value=selectedIntervals[0][0].toFixed(3);form.elements.end_seconds.value=selectedIntervals[0][1].toFixed(3)}document.querySelector('#markIn').classList.toggle('active',intervalStart!==null);const status=document.querySelector('#projectionStatus');if(status)status.textContent=selectedFrames.length?`Отмечено кадров: ${selectedFrames.length}. Повторная отметка обновит настройки кадра.`:'Сначала выберите кадр на видеодорожке.';drawAll()}
const graphSpecs=[['trackAltitude','Высота, м',['altitude_srt','height'],['SRT GPS','от взлёта'],['#177052','#d28b28']],['trackPosition','Смещение, м',['position_east','position_north'],['восток','север'],['#246a9c','#8d5fa8']],['trackDrone','Углы коптера, °',['drone_yaw','drone_pitch','drone_roll'],['yaw','pitch','roll'],['#177052','#d28b28','#8d5fa8']],['trackGimbal','Камера: мировые углы и yaw к корпусу, °',['gimbal_yaw','gimbal_relative_yaw','gimbal_pitch'],['yaw абс.','yaw отн.','pitch'],['#246a9c','#8d5fa8','#c74747']]];
const plotPad={l:72,r:14};
function sizeCanvas(c,h){const dpr=devicePixelRatio||1,w=Math.max(320,c.clientWidth||900);c.style.height=`${h}px`;if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr)}const g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);return [g,w]}
function xForTime(t,w){return plotPad.l+(t/viewer.video.duration)*(w-plotPad.l-plotPad.r)}
function timeForX(x,w){return Math.max(0,Math.min(viewer.video.duration,(x-plotPad.l)/(w-plotPad.l-plotPad.r)*viewer.video.duration))}
