function seriesAt(key,t=video.currentTime,circular=false){const a=viewer.series[key],p=Math.max(0,Math.min(a.length-1,t/viewer.video.duration*(a.length-1))),i=Math.floor(p),j=Math.min(a.length-1,i+1),f=p-i,start=Number(a[i]),end=Number(a[j]);if(circular){const delta=((end-start+540)%360)-180;return start+delta*f}return start+(end-start)*f}
function horizonAutoPercent(){if(!viewer)return 0;const pitch=seriesAt('gimbal_pitch')+DV.coast.pitchOffset()+DV.coast.dip(),zoom=seriesAt('zoom'),hfov=viewer.series.horizontal_fov_deg?seriesAt('horizontal_fov_deg'):2*Math.atan(Math.tan(66.1*Math.PI/360)/zoom)*180/Math.PI,vfov=2*Math.atan(Math.tan(hfov*Math.PI/360)*viewer.video.height/viewer.video.width)*180/Math.PI;return (.5+.5*Math.tan(pitch*Math.PI/180)/Math.tan(vfov*Math.PI/360))*100}
